diffs.patch:
Index: MEETING_BRIEF.html
===================================================================
--- MEETING_BRIEF.html	
+++ MEETING_BRIEF.html	
@@ -0,0 +1,2081 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8" />
+<meta name="viewport" content="width=device-width, initial-scale=1.0" />
+<title>SWA ERP — Client Meeting Brief</title>
+<style>
+  :root {
+    --bg: #0f1117;
+    --surface: #1a1d27;
+    --card: #1e2130;
+    --border: #2a2f45;
+    --accent: #5b6af5;
+    --accent2: #8b5cf6;
+    --green: #22c55e;
+    --yellow: #f59e0b;
+    --red: #ef4444;
+    --blue: #3b82f6;
+    --cyan: #06b6d4;
+    --text: #e2e8f0;
+    --muted: #64748b;
+    --dim: #94a3b8;
+  }
+  * { box-sizing: border-box; margin: 0; padding: 0; }
+  body {
+    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
+    background: var(--bg);
+    color: var(--text);
+    line-height: 1.6;
+    font-size: 15px;
+  }
+
+  /* ── NAV / COVER ── */
+  .cover {
+    background: linear-gradient(135deg, #0f1117 0%, #1a1040 50%, #0f1117 100%);
+    border-bottom: 1px solid var(--border);
+    padding: 60px 40px 50px;
+    text-align: center;
+    position: relative;
+    overflow: hidden;
+  }
+  .cover::before {
+    content: '';
+    position: absolute; inset: 0;
+    background: radial-gradient(ellipse 900px 400px at 50% 0%, rgba(91,106,245,0.18), transparent);
+    pointer-events: none;
+  }
+  .cover-badge {
+    display: inline-block;
+    background: rgba(91,106,245,0.15);
+    border: 1px solid rgba(91,106,245,0.4);
+    color: #a5b4fc;
+    padding: 4px 16px;
+    border-radius: 999px;
+    font-size: 12px;
+    letter-spacing: 1.5px;
+    text-transform: uppercase;
+    margin-bottom: 20px;
+  }
+  .cover h1 {
+    font-size: clamp(28px, 5vw, 52px);
+    font-weight: 700;
+    letter-spacing: -1px;
+    background: linear-gradient(135deg, #e2e8f0, #a5b4fc 60%, #c4b5fd);
+    -webkit-background-clip: text;
+    -webkit-text-fill-color: transparent;
+    background-clip: text;
+    margin-bottom: 12px;
+  }
+  .cover-sub {
+    color: var(--dim);
+    font-size: 17px;
+    margin-bottom: 36px;
+  }
+  .cover-meta {
+    display: flex;
+    justify-content: center;
+    gap: 40px;
+    flex-wrap: wrap;
+  }
+  .cover-meta-item {
+    text-align: center;
+  }
+  .cover-meta-item .label {
+    font-size: 11px;
+    color: var(--muted);
+    text-transform: uppercase;
+    letter-spacing: 1px;
+  }
+  .cover-meta-item .value {
+    font-size: 14px;
+    color: var(--dim);
+    margin-top: 2px;
+  }
+
+  /* ── LAYOUT ── */
+  .container {
+    max-width: 1100px;
+    margin: 0 auto;
+    padding: 0 24px;
+  }
+  .page { padding: 48px 0; }
+
+  /* ── SECTION HEADERS ── */
+  .section-tag {
+    font-size: 11px;
+    letter-spacing: 2px;
+    text-transform: uppercase;
+    color: var(--accent);
+    margin-bottom: 6px;
+  }
+  .section-title {
+    font-size: 26px;
+    font-weight: 700;
+    color: var(--text);
+    margin-bottom: 8px;
+  }
+  .section-desc {
+    color: var(--dim);
+    margin-bottom: 28px;
+    max-width: 640px;
+  }
+  .section-divider {
+    border: none;
+    border-top: 1px solid var(--border);
+    margin: 52px 0;
+  }
+
+  /* ── STAT CARDS ── */
+  .stat-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
+    gap: 16px;
+    margin-bottom: 32px;
+  }
+  .stat-card {
+    background: var(--card);
+    border: 1px solid var(--border);
+    border-radius: 12px;
+    padding: 20px 22px;
+    position: relative;
+    overflow: hidden;
+  }
+  .stat-card::before {
+    content: '';
+    position: absolute;
+    top: 0; left: 0; right: 0;
+    height: 3px;
+    border-radius: 12px 12px 0 0;
+  }
+  .stat-card.green::before { background: var(--green); }
+  .stat-card.yellow::before { background: var(--yellow); }
+  .stat-card.blue::before { background: var(--blue); }
+  .stat-card.purple::before { background: var(--accent2); }
+  .stat-card.cyan::before { background: var(--cyan); }
+
+  .stat-label {
+    font-size: 11px;
+    color: var(--muted);
+    text-transform: uppercase;
+    letter-spacing: 1px;
+    margin-bottom: 8px;
+  }
+  .stat-number {
+    font-size: 32px;
+    font-weight: 800;
+    line-height: 1;
+  }
+  .stat-number.green { color: var(--green); }
+  .stat-number.yellow { color: var(--yellow); }
+  .stat-number.blue { color: var(--blue); }
+  .stat-number.purple { color: var(--accent2); }
+  .stat-number.cyan { color: var(--cyan); }
+  .stat-sub {
+    font-size: 12px;
+    color: var(--muted);
+    margin-top: 4px;
+  }
+
+  /* ── PROGRESS BAR ── */
+  .progress-wrap {
+    background: var(--card);
+    border: 1px solid var(--border);
+    border-radius: 12px;
+    padding: 20px 24px;
+    margin-bottom: 24px;
+  }
+  .progress-header {
+    display: flex;
+    justify-content: space-between;
+    margin-bottom: 10px;
+  }
+  .progress-label { font-size: 14px; color: var(--dim); font-weight: 500; }
+  .progress-pct { font-size: 14px; color: var(--text); font-weight: 700; }
+  .progress-bar {
+    height: 10px;
+    background: var(--border);
+    border-radius: 999px;
+    overflow: hidden;
+  }
+  .progress-fill {
+    height: 100%;
+    border-radius: 999px;
+    background: linear-gradient(90deg, var(--accent), var(--cyan));
+    transition: width 0.3s ease;
+  }
+  .progress-note { font-size: 12px; color: var(--muted); margin-top: 8px; }
+
+  /* ── BADGES ── */
+  .badge {
+    display: inline-flex;
+    align-items: center;
+    gap: 5px;
+    padding: 3px 10px;
+    border-radius: 999px;
+    font-size: 12px;
+    font-weight: 600;
+  }
+  .badge.green { background: rgba(34,197,94,0.15); color: var(--green); }
+  .badge.yellow { background: rgba(245,158,11,0.15); color: var(--yellow); }
+  .badge.red { background: rgba(239,68,68,0.15); color: var(--red); }
+  .badge.blue { background: rgba(59,130,246,0.15); color: var(--blue); }
+  .badge.purple { background: rgba(139,92,246,0.15); color: var(--accent2); }
+  .badge.cyan { background: rgba(6,182,212,0.15); color: var(--cyan); }
+  .badge.gray { background: rgba(100,116,139,0.15); color: var(--muted); }
+
+  /* ── TABLES ── */
+  .tbl-wrap { overflow-x: auto; margin-bottom: 24px; border-radius: 12px; border: 1px solid var(--border); }
+  table { width: 100%; border-collapse: collapse; background: var(--card); }
+  thead th {
+    background: var(--surface);
+    padding: 12px 16px;
+    text-align: left;
+    font-size: 11px;
+    color: var(--muted);
+    text-transform: uppercase;
+    letter-spacing: 1px;
+    border-bottom: 1px solid var(--border);
+  }
+  tbody td {
+    padding: 12px 16px;
+    border-bottom: 1px solid rgba(42,47,69,0.5);
+    font-size: 14px;
+    color: var(--dim);
+    vertical-align: middle;
+  }
+  tbody tr:last-child td { border-bottom: none; }
+  tbody tr:hover td { background: rgba(91,106,245,0.04); }
+
+  /* ── FLOW DIAGRAM ── */
+  .flow {
+    display: flex;
+    flex-direction: column;
+    align-items: flex-start;
+    gap: 0;
+    margin: 24px 0;
+  }
+  .flow-item {
+    display: flex;
+    align-items: center;
+    gap: 16px;
+  }
+  .flow-node {
+    background: var(--card);
+    border: 1px solid var(--border);
+    border-radius: 10px;
+    padding: 10px 18px;
+    font-size: 14px;
+    font-weight: 600;
+    color: var(--text);
+    min-width: 220px;
+    position: relative;
+  }
+  .flow-node.highlight {
+    border-color: var(--accent);
+    background: rgba(91,106,245,0.08);
+  }
+  .flow-node .flow-id {
+    font-size: 11px;
+    color: var(--muted);
+    font-weight: 400;
+    margin-top: 2px;
+  }
+  .flow-arrow {
+    width: 2px;
+    height: 24px;
+    background: var(--border);
+    margin-left: 28px;
+    position: relative;
+  }
+  .flow-arrow::after {
+    content: '↓';
+    position: absolute;
+    bottom: -8px;
+    left: 50%;
+    transform: translateX(-50%);
+    color: var(--muted);
+    font-size: 14px;
+    background: var(--bg);
+    padding: 0 2px;
+  }
+  .flow-side {
+    font-size: 12px;
+    color: var(--muted);
+    max-width: 200px;
+  }
+
+  /* ── CARDS ── */
+  .card {
+    background: var(--card);
+    border: 1px solid var(--border);
+    border-radius: 12px;
+    padding: 20px 24px;
+    margin-bottom: 16px;
+  }
+  .card-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    margin-bottom: 12px;
+  }
+  .card-title {
+    font-size: 15px;
+    font-weight: 600;
+    color: var(--text);
+  }
+  .card-body {
+    font-size: 14px;
+    color: var(--dim);
+  }
+
+  /* ── GRID LAYOUTS ── */
+  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
+  .three-col { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }
+  @media (max-width: 768px) {
+    .two-col, .three-col { grid-template-columns: 1fr; }
+  }
+
+  /* ── TECH STACK ── */
+  .tech-pills {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 8px;
+    margin-top: 10px;
+  }
+  .tech-pill {
+    background: rgba(91,106,245,0.1);
+    border: 1px solid rgba(91,106,245,0.25);
+    color: #a5b4fc;
+    padding: 4px 12px;
+    border-radius: 999px;
+    font-size: 12px;
+    font-weight: 500;
+  }
+
+  /* ── DEMO STEPS ── */
+  .steps {
+    list-style: none;
+    display: flex;
+    flex-direction: column;
+    gap: 0;
+  }
+  .step {
+    display: flex;
+    gap: 16px;
+    position: relative;
+  }
+  .step::before {
+    content: '';
+    position: absolute;
+    left: 19px;
+    top: 40px;
+    bottom: -8px;
+    width: 2px;
+    background: var(--border);
+  }
+  .step:last-child::before { display: none; }
+  .step-num {
+    width: 38px;
+    height: 38px;
+    min-width: 38px;
+    background: rgba(91,106,245,0.15);
+    border: 1px solid rgba(91,106,245,0.35);
+    border-radius: 50%;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    font-size: 13px;
+    font-weight: 700;
+    color: #a5b4fc;
+    z-index: 1;
+  }
+  .step-body {
+    padding: 8px 0 24px;
+  }
+  .step-title {
+    font-size: 14px;
+    font-weight: 600;
+    color: var(--text);
+    margin-bottom: 4px;
+  }
+  .step-desc {
+    font-size: 13px;
+    color: var(--muted);
+  }
+  .step-code {
+    display: inline-block;
+    background: rgba(0,0,0,0.4);
+    border: 1px solid var(--border);
+    border-radius: 6px;
+    padding: 2px 8px;
+    font-family: 'Courier New', monospace;
+    font-size: 12px;
+    color: #93c5fd;
+    margin-top: 4px;
+  }
+
+  /* ── DECISION TABLE ── */
+  .decision-card {
+    background: var(--card);
+    border: 1px solid var(--border);
+    border-left: 3px solid var(--accent);
+    border-radius: 0 10px 10px 0;
+    padding: 16px 20px;
+    margin-bottom: 12px;
+    display: grid;
+    grid-template-columns: auto 1fr auto;
+    gap: 16px;
+    align-items: start;
+  }
+  .d-num {
+    font-size: 20px;
+    font-weight: 800;
+    color: rgba(91,106,245,0.4);
+  }
+  .d-question { font-size: 14px; font-weight: 600; color: var(--text); }
+  .d-rec {
+    font-size: 12px;
+    color: var(--green);
+    background: rgba(34,197,94,0.1);
+    border: 1px solid rgba(34,197,94,0.2);
+    padding: 4px 10px;
+    border-radius: 6px;
+    white-space: nowrap;
+    font-weight: 500;
+  }
+  .d-options {
+    grid-column: 2 / 3;
+    font-size: 13px;
+    color: var(--muted);
+    margin-top: 4px;
+  }
+
+  /* ── QUESTIONS LIST ── */
+  .q-item {
+    display: flex;
+    gap: 12px;
+    padding: 14px 18px;
+    background: var(--card);
+    border: 1px solid var(--border);
+    border-radius: 10px;
+    margin-bottom: 10px;
+    align-items: flex-start;
+  }
+  .q-num {
+    min-width: 26px;
+    height: 26px;
+    background: rgba(6,182,212,0.15);
+    border: 1px solid rgba(6,182,212,0.3);
+    border-radius: 50%;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    font-size: 11px;
+    font-weight: 700;
+    color: var(--cyan);
+  }
+  .q-text {
+    font-size: 14px;
+    color: var(--dim);
+    flex: 1;
+  }
+  .q-text strong { color: var(--text); }
+
+  /* ── RISK ── */
+  .risk-row {
+    display: grid;
+    grid-template-columns: 2fr 80px 80px 3fr;
+    gap: 12px;
+    padding: 14px 18px;
+    background: var(--card);
+    border-bottom: 1px solid rgba(42,47,69,0.4);
+    font-size: 13px;
+    align-items: center;
+  }
+  .risk-row:last-child { border-bottom: none; }
+  .risk-header {
+    display: grid;
+    grid-template-columns: 2fr 80px 80px 3fr;
+    gap: 12px;
+    padding: 10px 18px;
+    font-size: 11px;
+    color: var(--muted);
+    text-transform: uppercase;
+    letter-spacing: 1px;
+    background: var(--surface);
+    border-bottom: 1px solid var(--border);
+  }
+  .risk-wrap {
+    background: var(--card);
+    border: 1px solid var(--border);
+    border-radius: 12px;
+    overflow: hidden;
+  }
+
+  /* ── TIMELINE ── */
+  .timeline {
+    position: relative;
+    padding-left: 32px;
+  }
+  .timeline::before {
+    content: '';
+    position: absolute;
+    left: 7px;
+    top: 8px;
+    bottom: 0;
+    width: 2px;
+    background: var(--border);
+  }
+  .tl-item {
+    position: relative;
+    margin-bottom: 20px;
+  }
+  .tl-item::before {
+    content: '';
+    position: absolute;
+    left: -28px;
+    top: 6px;
+    width: 10px;
+    height: 10px;
+    background: var(--accent);
+    border-radius: 50%;
+    border: 2px solid var(--bg);
+  }
+  .tl-when {
+    font-size: 11px;
+    color: var(--accent);
+    font-weight: 600;
+    text-transform: uppercase;
+    letter-spacing: 0.5px;
+  }
+  .tl-what {
+    font-size: 14px;
+    color: var(--text);
+    margin-top: 2px;
+  }
+  .tl-who {
+    font-size: 12px;
+    color: var(--muted);
+    margin-top: 1px;
+  }
+
+  /* ── CHEAT SHEET ── */
+  .cheat-item {
+    background: var(--card);
+    border: 1px solid var(--border);
+    border-radius: 10px;
+    padding: 16px 20px;
+    margin-bottom: 12px;
+  }
+  .cheat-q {
+    font-size: 13px;
+    font-weight: 600;
+    color: var(--yellow);
+    margin-bottom: 8px;
+  }
+  .cheat-a {
+    font-size: 14px;
+    color: var(--dim);
+    border-left: 2px solid var(--accent);
+    padding-left: 12px;
+    font-style: italic;
+  }
+
+  /* ── MODULES GRID ── */
+  .modules-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
+    gap: 12px;
+    margin-bottom: 24px;
+  }
+  .module-card {
+    background: var(--card);
+    border: 1px solid var(--border);
+    border-radius: 10px;
+    padding: 14px 16px;
+  }
+  .module-card.passing { border-left: 3px solid var(--green); }
+  .module-card.partial { border-left: 3px solid var(--yellow); }
+  .module-card.failing { border-left: 3px solid var(--red); }
+  .module-card.untested { border-left: 3px solid var(--muted); }
+  .module-name {
+    font-size: 13px;
+    font-weight: 600;
+    color: var(--text);
+    margin-bottom: 6px;
+  }
+  .module-sheet {
+    font-size: 11px;
+    color: var(--muted);
+    margin-bottom: 8px;
+  }
+  .module-icons {
+    display: flex;
+    gap: 6px;
+    flex-wrap: wrap;
+  }
+
+  /* ── NAVBAR (print nav hidden) ── */
+  .nav {
+    position: sticky;
+    top: 0;
+    z-index: 100;
+    background: rgba(15,17,23,0.92);
+    backdrop-filter: blur(12px);
+    border-bottom: 1px solid var(--border);
+    padding: 0 24px;
+  }
+  .nav-inner {
+    max-width: 1100px;
+    margin: 0 auto;
+    display: flex;
+    align-items: center;
+    gap: 4px;
+    overflow-x: auto;
+    padding: 10px 0;
+    scrollbar-width: none;
+  }
+  .nav-inner::-webkit-scrollbar { display: none; }
+  .nav-link {
+    font-size: 12px;
+    color: var(--muted);
+    text-decoration: none;
+    padding: 5px 12px;
+    border-radius: 6px;
+    white-space: nowrap;
+    transition: all 0.15s;
+  }
+  .nav-link:hover { color: var(--text); background: rgba(255,255,255,0.05); }
+  .nav-logo {
+    font-size: 13px;
+    font-weight: 700;
+    color: #a5b4fc;
+    margin-right: 12px;
+    white-space: nowrap;
+  }
+
+  /* ── PRINT ── */
+  @media print {
+    body { background: white; color: #1a1a2e; }
+    .nav { display: none; }
+    .cover { background: #1a1a2e; }
+    .section-divider { border-color: #ccc; }
+    .card, .stat-card, .progress-wrap, .tbl-wrap,
+    .cheat-item, .risk-wrap, .q-item, .decision-card,
+    .module-card { border-color: #ddd; }
+  }
+</style>
+</head>
+<body>
+
+<!-- ═══════════════════════════════════════════════════════════
+     STICKY NAV
+═══════════════════════════════════════════════════════════ -->
+<nav class="nav">
+  <div class="nav-inner">
+    <span class="nav-logo">SWA ERP</span>
+    <a class="nav-link" href="#summary">Summary</a>
+    <a class="nav-link" href="#flow">Business Flow</a>
+    <a class="nav-link" href="#waves">Waves</a>
+    <a class="nav-link" href="#modules">20 Modules</a>
+    <a class="nav-link" href="#tech">Tech Stack</a>
+    <a class="nav-link" href="#demo">Demo Plan</a>
+    <a class="nav-link" href="#proof">Live Proof</a>
+    <a class="nav-link" href="#decisions">Decisions</a>
+    <a class="nav-link" href="#questions">Questions</a>
+    <a class="nav-link" href="#risks">Risks</a>
+    <a class="nav-link" href="#next">Next Steps</a>
+    <a class="nav-link" href="#checklist">✅ Pre-Meeting</a>
+    <a class="nav-link" href="#cheatsheet">Cheat Sheet</a>
+  </div>
+</nav>
+
+<!-- ═══════════════════════════════════════════════════════════
+     COVER
+═══════════════════════════════════════════════════════════ -->
+<div class="cover">
+  <div class="cover-badge">Confidential · Internal</div>
+  <h1>SWA ERP — Project Status</h1>
+  <p class="cover-sub">Client Meeting Brief · June 2026</p>
+  <div class="cover-meta">
+    <div class="cover-meta-item">
+      <div class="label">Duration</div>
+      <div class="value">60–90 min</div>
+    </div>
+    <div class="cover-meta-item">
+      <div class="label">Stage</div>
