 from __future__ import annotations

 import uuid

 from fastapi import APIRouter, Depends, HTTPException, Query, status
 from sqlalchemy.orm import Session

 from src.backend.core.deps import get_current_user, require_role
 from src.backend.core.roles import Role
 from src.backend.db.session import get_db
 from src.backend.models.user import User
 from src.backend.schemas.service_agreement import (
     ServiceAgreementCreate,
     ServiceAgreementListResponse,
     ServiceAgreementRead,
     ServiceAgreementUpdate,
 )
 from src.backend.services import agreement_service

 router = APIRouter(prefix="/api/agreements", tags=["agreements"])


 @router.get("", response_model=ServiceAgreementListResponse)
 def list_agreements(
     _: User = Depends(require_role(Role.PM)),  # noqa: B008
     db: Session = Depends(get_db),  # noqa: B008
     page: int = Query(default=1, ge=1),
     page_size: int = Query(default=20, ge=1, le=100),
     client_id: uuid.UUID | None = None,
     status_filter: str | None = Query(default=None, alias="status"),
 ) -> ServiceAgreementListResponse:
     items, total, page, page_size = agreement_service.list_agreements_service(
         db, page=page, page_size=page_size, client_id=client_id, status=status_filter
     )
     return ServiceAgreementListResponse(
         items=[ServiceAgreementRead.model_validate(a) for a in items],
         total=total,
         page=page,
         page_size=page_size,
     )


 @router.get("/by-client/{client_id}", response_model=ServiceAgreementListResponse)
 def list_agreements_by_client(
     client_id: uuid.UUID,
     _: User = Depends(get_current_user),  # noqa: B008
     db: Session = Depends(get_db),  # noqa: B008
     page: int = Query(default=1, ge=1),
     page_size: int = Query(default=20, ge=1, le=100),
 ) -> ServiceAgreementListResponse:
     items, total, page, page_size = agreement_service.list_agreements_by_client_service(
         db, client_id=client_id, page=page, page_size=page_size
     )
     return ServiceAgreementListResponse(
         items=[ServiceAgreementRead.model_validate(a) for a in items],
         total=total,
         page=page,
         page_size=page_size,
     )


 @router.post("", response_model=ServiceAgreementRead, status_code=status.HTTP_201_CREATED)
 def create_agreement(
     body: ServiceAgreementCreate,
     current_user: User = Depends(require_role(Role.PM)),  # noqa: B008
     db: Session = Depends(get_db),  # noqa: B008
 ) -> ServiceAgreementRead:
     try:
         agreement = agreement_service.create_agreement_service(db, body, current_user.id)
     except LookupError as e:
         raise HTTPException(status_code=404, detail=str(e)) from e
     return ServiceAgreementRead.model_validate(agreement)


 @router.get("/{agreement_id}", response_model=ServiceAgreementRead)
 def get_agreement(
     agreement_id: uuid.UUID,
     _: User = Depends(get_current_user),  # noqa: B008
     db: Session = Depends(get_db),  # noqa: B008
 ) -> ServiceAgreementRead:
     agreement = agreement_service.get_agreement_service(db, agreement_id)
     if not agreement:
         raise HTTPException(status_code=404, detail="Agreement not found")
     return ServiceAgreementRead.model_validate(agreement)


